package local.quickpic.crop27;
import android.app.*;import android.content.*;import android.content.pm.*;import android.graphics.*;import android.media.ExifInterface;import android.os.*;import android.view.*;import android.widget.*;import java.io.*;import java.lang.reflect.*;import java.util.*;
public class Probe extends Instrumentation {
 boolean previewOnly; int passed;Class<?> image,cropType;Context target;File dir;List<String> checks=new ArrayList<>();
 void check(boolean b,String name){if(!b)throw new AssertionError(name);passed++;checks.add(name);android.util.Log.i("Crop27Probe",passed+" "+name);}
 Object field(Object o,String n)throws Exception{Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);return f.get(o);}
 void tick() {try{Thread.sleep(180);}catch(Exception e){}}
 File render(File source,int w,int h,Object c)throws Exception{return (File)image.getMethod("prepare",String.class,int.class,int.class,File.class,boolean.class,cropType).invoke(null,source.getAbsolutePath(),w,h,dir,false,c);}
 Object c(double l,double t,double w,double h)throws Exception{return cropType.getConstructor(double.class,double.class,double.class,double.class).newInstance(l,t,w,h);}
 void touch(View v,int action,float x,float y){runOnMainSync(()->{MotionEvent e=MotionEvent.obtain(SystemClock.uptimeMillis(),SystemClock.uptimeMillis(),action,x,y,0);v.dispatchTouchEvent(e);e.recycle();});tick();}
 void pinch(View v,int action,float x,float y,float distance,long down){runOnMainSync(()->{MotionEvent.PointerProperties[] props={new MotionEvent.PointerProperties(),new MotionEvent.PointerProperties()};MotionEvent.PointerCoords[] coords={new MotionEvent.PointerCoords(),new MotionEvent.PointerCoords()};for(int i=0;i<2;i++){props[i].id=i;props[i].toolType=1;coords[i].x=x+(i==0?-distance:distance);coords[i].y=y;coords[i].pressure=1;coords[i].size=1;}MotionEvent e=MotionEvent.obtain(down,SystemClock.uptimeMillis(),action,2,props,coords,0,0,1,1,0,0,InputDevice.SOURCE_TOUCHSCREEN,0);v.dispatchTouchEvent(e);e.recycle();});tick();}
 @Override public void onCreate(Bundle args){super.onCreate(args);previewOnly=args!=null&&Boolean.parseBoolean(args.getString("preview","false"));start();}
 @Override public void onStart(){Bundle out=new Bundle();try{
 target=getTargetContext();if(previewOnly){Intent preview=new Intent().setClassName(target.getPackageName(),"com.alensw.jni.ScreensaverCropActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK).putExtra("source",new File(target.getCacheDir(),"crop27-synthetic/quadrants.jpg").getAbsolutePath()).putExtra("backend",0).putExtra("width",1860).putExtra("height",2480);Activity a=startActivitySync(preview);Thread.sleep(12000);runOnMainSync(()->a.finish());finish(Activity.RESULT_OK,new Bundle());return;}ClassLoader loader=target.getClassLoader();image=loader.loadClass("com.alensw.jni.ScreensaverImage");cropType=loader.loadClass("com.alensw.jni.ScreensaverImage$Crop");dir=new File(target.getCacheDir(),"crop27-synthetic");dir.mkdirs();
 Bitmap raw=Bitmap.createBitmap(600,400,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(raw);Paint paint=new Paint();int[] colors={Color.RED,Color.GREEN,Color.BLUE,Color.YELLOW};for(int i=0;i<4;i++){paint.setColor(colors[i]);canvas.drawRect(i%2*300,i/2*200,(i%2+1)*300,(i/2+1)*200,paint);}
 File source=new File(dir,"quadrants.jpg");try(FileOutputStream stream=new FileOutputStream(source)){raw.compress(Bitmap.CompressFormat.JPEG,100,stream);}raw.recycle();
 int[] expected={0,0,1,3,2,0,2,3,1};
 for(int orientation=1;orientation<=8;orientation++){ExifInterface exif=new ExifInterface(source.getAbsolutePath());exif.setAttribute(ExifInterface.TAG_ORIENTATION,""+orientation);exif.saveAttributes();int sw=orientation>=5?400:600,sh=orientation>=5?600:400,w=sw/10,h=sh/10;File result=render(source,w,h,c(0,0,sw/4.0,sh/4.0));Bitmap b=BitmapFactory.decodeFile(result.getAbsolutePath());int color=b.getPixel(w/2,h/2),wanted=colors[expected[orientation]];check(Math.abs(Color.red(color)-Color.red(wanted))<20&&Math.abs(Color.green(color)-Color.green(wanted))<20&&Math.abs(Color.blue(color)-Color.blue(wanted))<20,"EXIF "+orientation+" chosen corner");check(b.getWidth()==w&&b.getHeight()==h,"EXIF "+orientation+" exact output size");b.recycle();}
 ExifInterface exif=new ExifInterface(source.getAbsolutePath());exif.setAttribute(ExifInterface.TAG_ORIENTATION,"1");exif.saveAttributes();
 boolean invalid=false;try{render(source,120,160,c(-1,0,120,160));}catch(InvocationTargetException e){invalid=true;}check(invalid,"reject outside image before OEM");
 invalid=false;try{render(source,120,160,c(0,0,120,150));}catch(InvocationTargetException e){invalid=true;}check(invalid,"reject changed aspect before OEM");
 File saved=render(source,120,160,c(100,0,240,320));Class<?> copier=loader.loadClass("com.alensw.jni.ScreensaverImportCopy");File copy=(File)copier.getMethod("copy",File.class,File.class,int.class,int.class).invoke(null,saved,new File(dir,"import"),120,160);check(!saved.equals(copy)&&Arrays.equals(read(saved),read(copy)),"OEM copy byte identical and separate");copy.delete();check(saved.isFile(),"OEM input deletion preserves archive");
 File album=new File(Environment.getExternalStoragePublicDirectory(Environment.DIRECTORY_PICTURES),"QuickPic-Screensaver");album.mkdirs();new File(album,".nomedia").createNewFile();File old=new File(album,"old-saved.png");try(FileOutputStream stream=new FileOutputStream(old)){stream.write(read(saved));}
 check(!target.getPackageManager().getActivityInfo(new ComponentName(target.getPackageName(),"com.alensw.jni.ScreensaverCropActivity"),0).exported,"crop activity private");
 for(int order=0;order<3;order++){int backend=(order+1)%3;
  Intent intent=new Intent().setClassName(target.getPackageName(),"com.alensw.jni.ScreensaverCropActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK).putExtra("source",source.getAbsolutePath()).putExtra("backend",backend).putExtra("width",120).putExtra("height",160);
  Activity activity=startActivitySync(intent);View view=null;for(int i=0;i<80;i++){view=(View)field(activity,"crop");if(view!=null&&view.getWidth()>0)break;tick();}
  check(view!=null&&view.getWidth()>0,"backend "+backend+" custom editor loads");final View v=view;RectF box=(RectF)field(v,"box"),display=(RectF)field(v,"display");float f=display.width()/600;float x=display.left+box.centerX()*f,y=display.top+box.centerY()*f;
  RectF before=new RectF(box);touch(v,0,x,y);touch(v,2,x+35*f,y);touch(v,1,x+35*f,y);check(box.left>before.left&&Math.abs(box.width()-before.width())<0.1,"backend "+backend+" drag moves without resizing");
  float rx=display.left+box.right*f,by=display.top+box.bottom*f;before.set(box);touch(v,0,rx+4,by+4);touch(v,2,rx+4,by+4);check(Math.abs(box.width()-before.width())<0.1,"backend "+backend+" no handle jump");touch(v,2,rx-60*f,by-80*f);touch(v,1,rx-60*f,by-80*f);check(box.width()<before.width()&&Math.abs(box.width()/box.height()-0.75)<0.0001,"backend "+backend+" corner resize locks ratio");
  x=display.left+box.centerX()*f;y=display.top+box.centerY()*f;before.set(box);touch(v,0,x-180,y);long down=SystemClock.uptimeMillis();pinch(v,5|(1<<8),x,y,180,down);pinch(v,2,x,y,250,down);pinch(v,2,x,y,300,down);pinch(v,6|(1<<8),x,y,300,down);touch(v,1,x,y);check(Math.abs(box.width()/box.height()-0.75)<0.0001&&box.width()>before.width(),"backend "+backend+" pinch resize locks ratio");
  if(backend==0){int countBefore=album.listFiles((d,n)->n.startsWith("screensaver-")&&n.endsWith(".png")).length;runOnMainSync(()->((Button)uncheckedField(activity,"confirm")).performClick());File found=null;for(int i=0;i<100;i++){File[] fs=album.listFiles((d,n)->n.startsWith("screensaver-")&&n.endsWith(".png"));if(fs!=null&&fs.length>countBefore){Arrays.sort(fs,(a,b)->Long.compare(b.lastModified(),a.lastModified()));found=fs[0];break;}tick();}check(found!=null,"custom result permanently saved in Pictures album");Bitmap b=BitmapFactory.decodeFile(found.getAbsolutePath());check(b.getWidth()==120&&b.getHeight()==160,"custom output uses configured size");b.recycle();check(old.isFile()&&!new File(album,".nomedia").exists(),"previous image retained and album visible");out.putString("saved_png",found.getAbsolutePath());}
  else runOnMainSync(()->activity.finish());tick();
 }
 out.putString("checks",checks.toString());out.putInt("passed",passed);out.putString("scope","Real Android decoder and crop UI; no OEM calls, no physical screen test");finish(Activity.RESULT_OK,out);
 }catch(Throwable e){out.putString("failure",android.util.Log.getStackTraceString(e));out.putInt("passed",passed);finish(Activity.RESULT_CANCELED,out);}}
 Object uncheckedField(Object o,String n){try{return field(o,n);}catch(Exception e){throw new RuntimeException(e);}}
 byte[] read(File f)throws Exception{ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(FileInputStream in=new FileInputStream(f)){byte[] buf=new byte[8192];int n;while((n=in.read(buf))!=-1)bytes.write(buf,0,n);}return bytes.toByteArray();}
}
